using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Scene action fields Mutagen named after their signatures get xEdit's names. Three are also type fixes:
// a camera shot's ALLA is a placed reference (it was an Int32, so the link was never remapped), its LVCR is a float,
// and a timeline action's SNAM is a float start time. FLMV becomes flags on FX and Move actions.
// Each test reads a whole scene from Starfield.esm with both readers and writes it back byte for byte.
public class SceneActionFieldNameTests
{
    private static IEnumerable<ISceneGetter> Read(string hex)
        => ReadBoth<ISceneGetter>(Record("SCEN", Hex(hex)), f => Scene.CreateFromBinary(f), (s, p) => SceneBinaryOverlay.SceneFactory(s, p));

    private static void WritesBack(ISceneGetter scen, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => scen.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // MS03_Juno_Decision (0D2881:Starfield.esm)
    private const string Juno = "";

    // HailTemplate_100c_KT04_HailRefuse (0251A5:Starfield.esm)
    private const string Hail = "";

    // COM_SarahMorgan_System_RomanceSceneTeleport (318F0C:Starfield.esm)
    private const string Move = "";

    [Fact]
    public void CameraShot_LocationReferenceIsALink()
    {
        foreach (var scen in Read(Juno))
        {
            var shot = scen.Actions!.OfType<ICameraSceneActionGetter>().Single().CameraShots!.Single();
            shot.CameraLocationReference.FormKey.ID.ShouldBe(0x0C8037u);
            shot.LookTargetReference.FormKey.ID.ShouldBe(0x0C8037u);
            shot.LookTargetAlias.ShouldBe(-1);
            shot.CameraLocationAlias.ShouldBe(-1);
            shot.DelayStartTimeAction.ShouldBe(0f);
            shot.UseCameraLocationReference.ShouldBeTrue();
            shot.UseLookTargetReference.ShouldBeTrue();
            shot.UseCameraLocationAlias.ShouldBeFalse();
            scen.Actions!.OfType<IDialogueSceneActionGetter>().Single().VoiceOverride.ShouldNotBeNull();
            WritesBack(scen, Juno);
        }
    }

    [Fact]
    public void Fx_Flags()
    {
        foreach (var scen in Read(Hail))
        {
            var fx = scen.Actions!.OfType<IFxSceneActionGetter>().Single();
            fx.FxFlags.ShouldBe(FxSceneAction.Flag.FadeOut | FxSceneAction.Flag.FaderBlack | FxSceneAction.Flag.UseSoundFile);
            fx.Sound.ShouldNotBeNull();
            fx.FadeOutTime.ShouldBe(0f);
            WritesBack(scen, Hail);
        }
    }

    [Fact]
    public void Move_Flags()
    {
        foreach (var scen in Read(Move))
        {
            var move = scen.Actions!.OfType<IMoveSceneActionGetter>().Single();
            move.MoveFlags.ShouldBe(MoveSceneAction.Flag.TargetAlias);
            move.TargetAlias.ShouldBe(5);
            move.TargetReference.IsNull.ShouldBeTrue();
            WritesBack(scen, Move);
        }
    }
}
